def transform(grid):
    n = len(grid)

    # Extract non-zero value from each column (appearing on diagonal)
    col_values = [[] for _ in range(n)]
    for col in range(n):
        val = None
        for row in range(col, n):
            if grid[row][col] != 0:
                val = grid[row][col]
        if val is not None:
            col_values[col].append(val)

    # Get base sequence from first column's values
    base_seq = []
    for col in range(n):
        if col_values[col]:
            base_seq.append(col_values[col][0])

    # Shift the sequence for each row
    output = []
    for row_idx in range(n):
        shifted = base_seq[row_idx:] + base_seq[:row_idx]
        # Interleave with original values from that row's diagonal
        output.append(shifted.copy())

    return output
