def transform(grid):
    n_rows = len(grid)
    n_cols = len(grid[0])

    # Extract stripe values (first cell of each non-zero row) in input order
    stripe_rows = []
    for i, row in enumerate(grid):
        if any(val != 0 for val in row):
            stripe_rows.append(row[0])

    # Count frequencies
    freq = {}
    for v in stripe_rows:
        freq[v] = freq.get(v, 0) + 1

    # Sort by frequency ascending, then by first appearance index (input order)
    sorted_values = []
    for v in stripe_rows:
        sorted_values.append(v)

    # Build sorted order: by freq ascending, ties broken by first appearance
    indices = sorted(range(len(sorted_values)), key=lambda i: (freq[sorted_values[i]], i))
    sorted_order = [sorted_values[i] for i in indices]

    # Output repeats the sorted pattern
    output = []
    for i in range(n_rows):
        output.append([sorted_order[i % len(sorted_order)]] * n_cols)

    return output
